import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Johny Placide', position: 'GK', age: 38, club: 'Bastia', captain: true, bio: {"es":"La carrera de Johny Placide se ha basado en la paciencia, la resiliencia y la autoridad obtenidas a duras penas. Desarrollado en Le Havre, se abrió camino en el fútbol francés antes de convertirse en la última línea defensiva de confianza del Bastia. No llamativo, pero tremendamente confiable, Placide es conocido por sus reflejos agudos, su fuerte posicionamiento y sus manos seguras, cualidades que le valieron el apodo de \"El Guardián\". Manda su área vocalmente, sobresale bajo presión y lee el juego con la calma de un veterano. Nacido en Montfermeil, Francia, de padres haitianos, eligió representar a Haití, abrazando sus raíces con orgullo. Placide, pilar desde 2011 y, a menudo, capitán, ha guiado a sus compañeros más jóvenes a través de campañas exigentes, convirtiéndose en un pilar de estabilidad durante el histórico impulso de clasificación. Cuando el sueño de 2026 se hizo realidad, declaró: “Estaremos allí para disfrutarlo y enorgullecer a la gente”.","en":"Johny Placide’s career has been built on patience, resilience, and authority earned the hard way. Developed at Le Havre, he worked his way through French football before becoming a trusted last line of defence for Bastia. Not flashy, but fiercely reliable, Placide is known for sharp reflexes, strong positioning and safe hands, qualities that earned him the nickname “The Guardian.” He commands his area vocally, excels under pressure, and reads the game with the calm of a veteran. Born in Montfermeil, France, to Haitian parents, he chose to represent Haiti, embracing his roots with pride. A mainstay since 2011 and often captain, Placide has guided younger teammates through demanding campaigns, becoming a pillar of stability during the historic qualification push. As the dream of 2026 became reality, he declared: “We’ll be there to enjoy it and make the people proud.”"}, special: "Reliable" },
  { number: 12, name: 'Alexandre Pierre', position: 'GK', age: 25, club: 'Sochaux', bio: {"es":"En las jaulas de Aubervilliers, al norte de París, Alexandre Pierre aprendió a volar. Hijo de ascendencia haitiana, se lanzaba a través de las canchas mucho antes de tener los guantes adecuados, persiguiendo un sueño que se extendía mucho más allá de la periferia. Hoy, con 1,91m, domina su box con autoridad. Rápido en su línea y bendecido con reflejos felinos que convierten ciertos goles en jadeos. El camino de Pierre pasó por Stade Lavallois, Angers y Estrasburgo, donde firmó su primer contrato profesional en 2021, para luego afilar sus garras cedido en Annecy. Para Haití, se ha convertido en parte de una nueva generación que se atreve a pensar en grande, participando en competiciones de Concacaf y eliminatorias para la Copa del Mundo. Tranquilo pero tremendamente competitivo, Pierre juega como un hombre que todavía se lanza sobre el cemento. Cada salvada personal, cada portería a cero, una promesa cumplida.","en":"In the cages of Aubervilliers, just north of Paris, Alexandre Pierre learned to fly. A son of Haitian heritage, he would hurl himself across pitches long before he had proper gloves, chasing a dream that stretched far beyond the périphérique. Today, at 1.91m, he commands his box with authority. Quick off his line and blessed with cat-like reflexes that turn certain goals into gasps. Pierre’s path wound through Stade Lavallois, Angers and Strasbourg, where he signed his first professional deal in 2021, later sharpening his claws on loan at Annecy. For Haiti, he has become part of a new generation daring to think bigger, featuring in Concacaf competitions and World Cup qualifiers. Calm but fiercely competitive, Pierre plays like a man still diving on concrete. Every save personal, every clean sheet a promise kept."} },
  { number: 23, name: 'Josué Duverger', position: 'GK', age: 26, club: 'Cosmos Koblenz', bio: {"es":"En una noche húmeda durante la campaña de clasificación de Haití, Josué Duverger estaba solo bajo los focos, el ruido aumentaba y lo que estaba en juego era aún mayor. Tenía sólo 17 años cuando decidió representar a Haití, un adolescente con guantes un poco demasiado grandes y reservas de coraje igualmente descomunales. Nacido en Montreal y perfeccionado en las academias de Portugal, Duverger combina la técnica latina con el fuego caribeño. Rápido, valiente en el aire y ágil en el uno contra uno, es el tipo de portero que parece crecer cuando los tiros vuelan hacia él. A nivel de clubes, ha logrado impresionantes rachas sin recibir goles, incluida una tasa de blanqueadas del 50% durante una temporada en el Campeonato de Portugal. Ha habido lecciones contundentes, incluido un humillante gol en propia meta contra Canadá, su país natal y al que había representado en la categoría Sub-17, pero la historia de Duverger no se trata de errores. Se trata de respuesta: zambullirse. Elevar. Repetir.","en":"On a humid night during Haiti’s qualifying campaign, Josué Duverger stood alone beneath the floodlights, the noise rising, the stakes even higher. He was just 17 when he chose to represent Haiti, a teenager with gloves slightly too big and similarly outsized reserves of courage. Born in Montréal and honed in Portugal’s academies, Duverger blends Latin technique with Caribbean fire. Quick, brave in the air and spring-heeled in one-on-ones, he is the kind of goalkeeper who seems to grow taller as shots fly toward him. At club level he has posted impressive clean-sheet runs, including a 50% shut-out rate during a season in Portugal’s Campeonato. There have been bruising lessons, including a humiliating double-miskick own-goal against Canada, the country of his birth and which he had represented at Under-17 level, but Duverger’s story is not about mistakes. It is about response: Dive. Rise. Repeat."} },
  // Defensores
  { number: 2, name: 'Carlens Arcus', position: 'DF', age: 29, club: 'Angers', bio: {"es":"Desde las animadas calles de Puerto Príncipe, donde disfrutó de lo que describe como “una infancia muy feliz y muy pacífica”, hasta el rugido de las finales de la Copa Oro de la Concacaf, Arcus ha portado los desafíos con orgullo, como insignias. Rápido, intrépido en ataque y poseedor de una tremenda resistencia, encarna al lateral moderno: defensor primero, creador cuando es necesario y competidor siempre. Un pilar de la selección nacional de Haití desde 2016, Arcus entregó el centro que selló el primer lugar de Haití en la Copa del Mundo desde 1974, poniendo fin a una sequía de 51 años. \"Siempre tuve dos sueños en mi vida\", dijo después. \"Ya había conseguido lo primero, que era firmar un contrato profesional. Lo segundo acaba de hacerse realidad\". Arcus llamó la atención por primera vez en Francia con el Auxerre, donde sus carreras superpuestas y su consistencia lo hicieron indispensable, antes de refinar su juego con el Vitesse Arnhem en Holanda.","en":"From the spirited streets of Port-au-Prince, where he enjoyed what he describes as “a very happy, very peaceful childhood”, to the roar of Concacaf Gold Cup finals, Arcus has worn challenges with pride, like badges. Fast, fearless in attack and possessing tremendous stamina, he embodies the modern full-back: defender first, creator when it counts, and competitor always. A pillar of the Haiti national team since 2016, Arcus delivered the cross that sealed Haiti’s first World Cup berth since 1974, ending a 51-year drought. “I always had two dreams in my life,” he said afterwards. “I’d already achieved the first, which was to sign a professional contract. The second has just come true.” Arcus first caught the eye in France with Auxerre, where his overlapping runs and consistency made him indispensable, before refining his game with Vitesse Arnhem in the Netherlands."} },
  { number: 3, name: 'Keeto Thermoncy', position: 'DF', age: 0, club: 'Young Boys', bio: {"es":"Cuando Thermoncy se viste con los colores de Haití, lleva dos identidades en cada paso. Criado en Suiza pero fuertemente conectado con sus raíces haitianas, el joven defensor explicó una vez su vínculo con la selección nacional: “Cuando miras la historia de Haití y toda su gente ha resistido durante décadas, vestir esta camiseta significa mucho más que fútbol”. Es el tipo de reflexión que revela la madurez detrás de una de las perspectivas jóvenes más brillantes de Haití. Forjado en los disciplinados pasillos de la academia del Young Boys (pero aún sin aparecer en el primer equipo), Thermoncy es un central moderno: rápido en el césped, dominante en el aire y lo suficientemente tranquilo como para lanzar ataques desde lo profundo. Con más de 1,80 m, combina potencia atlética con sincronización elegante, deslizándose en las entradas con la seguridad de un profesional experimentado. Su debut con la selección absoluta en Haití en las eliminatorias para la Copa del Mundo se sintió menos como un primer paso que como una declaración. Ahora, Thermoncy ya parece estar preparado para anclar a la próxima generación de Haití.","en":"When Thermoncy pulls on Haiti’s colours, he carries two identities in every stride. Raised in Switzerland but fiercely connected to his Haitian roots, the young defender once explained his bond with the national team: “When you look at Haiti’s history and all its people have endured for decades, wearing this shirt means far more than football.” It is the kind of reflection that reveals the maturity behind one of Haiti’s brightest young prospects. Forged in the disciplined academy corridors of Young Boys (but still to make a first-team appearance), Thermoncy is a modern centre-back: quick across the turf, commanding in the air and calm enough to launch attacks from deep. At over 1.80m, he marries athletic power with elegant timing, gliding into tackles with the assurance of a seasoned professional. His senior Haiti debut in World Cup qualifying felt less like a first step than a statement. Now, Thermoncy already looks built to anchor Haiti’s next generation."} },
  { number: 4, name: 'Ricardo Adé', position: 'DF', age: 36, club: 'LDU Quito', bio: {"es":"Por algo le llaman El Muro. Ricardo Adé no sólo defiende; él controla el juego desde atrás, apagando los ataques incluso antes de que comiencen. Rápido en sus pies pero imbatible en el aire, lee el campo como un gran maestro, y su racha intrépida ancló la defensa de Haití durante años. La historia de Adé es incluso más inspiradora que sus actuaciones. Al principio de su carrera, se quedó varado en Tailandia después de una mudanza fallida, sobreviviendo con poco más que pan y leche condensada durante una semana; una prueba que forjó la resiliencia detrás del jugador. En la Liga de Quito, sus potentes cabezazos y su tranquila distribución han convertido partidos tensos en triunfos, ayudándolo a levantar cuatro trofeos nacionales. “Defender se trata de leer el juego y estar preparado para la batalla”, dice, y cada duelo lo demuestra. Fuera del campo, Adé mantiene la misma autoridad silenciosa y representa la identidad haitiana con orgullo y profesionalismo dondequiera que vaya.","en":"They call him The Wall for a reason. Ricardo Adé doesn’t just defend; he commands the game from the back, snuffing out attacks before they even begin. Quick on his feet yet unbeatable in the air, he reads the pitch like a grandmaster, his fearless streak anchoring Haiti’s defence for years. Adé’s story is even more inspiring than his performances. Early in his career, he was left stranded in Thailand after a failed move, surviving on little more than bread and condensed milk for a week; an ordeal that forged the resilience behind the player. At Liga de Quito, his booming headers and calm distribution have turned tense matches into triumphs, helping him lift four domestic trophies. “Defending is about reading the game and being ready for the battle,” he says, and every duel proves it. Off the field, Adé carries the same quiet authority, representing Haitian identity with pride and professionalism wherever he goes."}, special: "‘The Wall’" },
  { number: 5, name: 'Hannes Delcroix', position: 'DF', age: 27, club: 'Lugano', bio: {"es":"Nacido en Haití y criado en Bélgica, Delcroix creció entre dos culturas futbolísticas: el espíritu caribeño y la precisión europea. En Anderlecht perfeccionó su oficio; en Burnley aprendió el doloroso arte de la supervivencia y la necesidad de tener paciencia. “Mis características son las de alguien tranquilo, fuera y también dentro del campo”, dice y, tras pasar de Waalwijk a Burnley en 2023, tenía que estar tranquilo mientras esperaba su oportunidad. Al final se dio cuenta de que no llegaría y, tras quedar fuera de la lista de convocados al inicio de la temporada, buscó “un club que me garantizara mucho tiempo de juego y un papel importante”. Lo encontró en Lugano. Su debut internacional se produjo en octubre y rápidamente se convirtió en titular habitual. Rápido en el césped y dominante en el aire, Delcroix es el tipo de defensa central que entra al mediocampo con tranquila autoridad antes de lanzar una diagonal de 40 yardas como si fuera algo natural. Los entrenadores elogian su sincronización; Los compañeros de equipo hablan de su voz: firme, serena, intransigente.","en":"Born in Haiti and raised in Belgium, Delcroix grew up between two football cultures, Caribbean spirit and European precision. At Anderlecht he polished his craft; at Burnley he learned the bruising art of survival – and the need for patience. “My characteristics are someone who’s calm, off the pitch and also on the pitch,” he says and, after moving from Waalwijk to Burnley in 2023, he had to be calm as he waited for his chance. Eventually he realised it would not come, and after he was left out of their squad list at the start of the season he sought “a club that would guarantee me plenty of playing time and an important role”. He found that at Lugano. His international debut followed in October and he swiftly became a regular starter. Quick across the turf and dominant in the air, Delcroix is the kind of centre-back who steps into midfield with calm authority before launching a 40-yard diagonal as if it were second nature. Coaches praise his timing; teammates talk about his voice: steady, composed, uncompromising."} },
  { number: 8, name: 'Martin Expérience', position: 'DF', age: 26, club: 'AS Nancy', bio: {"es":"Hay algo apropiado en el apellido de Martin Expérience. Sobre el terreno de juego, juega con una experiencia superior a su edad. Nacido en Francia pero orgulloso de sus raíces haitianas, se abrió camino a través de las difíciles divisiones inferiores antes de ganarse su lugar en el Nancy, donde está cambiando la oscuridad por gradas llenas y escenarios más grandes, como parte del equipo que ganó el ascenso a la Ligue 2 en 2025. Cuando Haití selló su lugar en la Copa del Mundo de 2026, Expérience apenas pudo contenerse. \"Jugar un Mundial es extraordinario, sin importar a quién nos enfrentemos\", dijo, antes de que el sorteo los emparejara con Brasil, el país de su ídolo de la infancia, Neymar. Desde que debutó con Haití en 2021, ha aportado acero y resistencia a la línea defensiva de los Grenadiers, un lateral moderno formado por kilómetros duros, grandes sueños y una bandera que porta con orgullo.","en":"There’s something fitting about Martin Expérience’s surname. On the pitch, he plays with experience beyond his years. Born in France but proudly tied to his Haitian roots, he carved his path through the rugged lower divisions before earning his place with Nancy, where he is swapping obscurity for packed terraces and bigger stages, as part of the team that won promotion to Ligue 2 in 2025. When Haiti sealed their place at the 2026 World Cup, Expérience could hardly contain himself. “Playing in a World Cup is extraordinary, no matter whom we face,” he said - before the draw paired them with Brazil, the country of his childhood idol, Neymar. Since debuting for Haiti in 2021 he has brought steel and stamina to the Grenadiers’ back line, a modern full-back shaped by hard miles, big dreams and a flag he wears with pride."}, special: "Modern full-back" },
  { number: 13, name: 'Duke Lacroix', position: 'DF', age: 32, club: 'Colorado Springs Switchbacks', bio: {"es":"Antes de merodear por el flanco de Haití, Duke Lacroix era un estudiante atleta en la Universidad de Pensilvania, compaginando sus clases (obtuvo una licenciatura en sociología y luego una maestría en psicología deportiva) con sueños que se extendían mucho más allá del campus. Rápido, intrépido y bendecido con el motor de un velocista, Lacroix juega de lateral izquierdo como un extremo disfrazado. Bombardea hacia adelante, lanza centros, gana sus cabezazos a pesar de no ser el más alto y se recupera con un ritmo impresionante. Desde que se comprometió con la selección nacional de fútbol de Haití en 2023, Lacroix ha lucido los colores con orgullo, atacando cada duelo como si fuera personal. Fuera del fútbol, ​​está involucrado en política y activismo social, como vicepresidente de United Black Players, presidente de la Asociación de Jugadores de la USL, el sindicato que representa a los jugadores de la United Soccer League, y trabaja para Onrise, que brinda apoyo de salud mental a atletas y otras personas en roles de alta presión.","en":"Before he was marauding down the flank for Haiti, Duke Lacroix was a student athlete at the University of Pennsylvania, balancing lectures - he got a degree in sociology, and followed it with a master’s in sports psychology - with dreams that stretched far beyond campus. Fast, fearless, and blessed with a sprinter’s engine, Lacroix plays left-back like a winger in disguise. He bombs forward, whips in crosses, wins his headers despite not being the tallest, and recovers with impressive pace. Since committing to the Haiti national football team in 2023 Lacroix has worn the colours with pride, attacking every duel as if it were personal. Outside football he is involved in politics and social activism, as vice president of United Black Players, president of the USL Players Association, the union representing players in the United Soccer League, and working for Onrise, who provide mental health support to athletes and others in high-pressure roles."}, special: "Social activist" },
  { number: 22, name: 'Jean-Kévin Duverne', position: 'DF', age: 28, club: 'Nantes', bio: {"es":"La historia de Jean‑Kévin Duverne es de silenciosa tenacidad y respeto ganado con esfuerzo. En un campo bañado por el sol en la Guayana Francesa en 2024, cuando levantó el brazo hacia el cielo después de abrazar su primera gorra con Haití, había una emoción palpable, no solo otro defensor que debutaba, sino un granadero que reivindicaba su derecho a nivel internacional. Ese momento fue la culminación de años en las implacables ligas francesas, donde aprendió a combinar su ritmo crudo con una determinación defensiva inquebrantable. Esta temporada ha ejercido su oficio en Bélgica con Gent cedido por Nantes, este intrépido y atlético defensor se siente tan cómodo dirigiendo la línea de fondo como provocando ataques desde lo profundo. Duverne se ha convertido en un símbolo de orgullo para los aficionados haitianos, un guardián en el corazón de sus esperanzas y una historia que aún se desarrolla. Fuera de la cancha, es tranquilo pero intenso, una presencia firme cuya historia aún se está escribiendo, una entrada intrépida a la vez.","en":"Jean‑Kévin Duverne’s story is one of quiet tenacity and hard‑earned respect. On a sun‑drenched pitch in French Guiana in 2024, when he lifted his arm skyward after clasping that first Haiti cap, there was a palpable thrill, not just another defender making his debut, but a Grenadier staking his claim at international level. The moment was the culmination of years in France’s unforgiving leagues, where he learned to mix his raw pace with unwavering defensive grit. This season he has  plied his trade in Belgium with Gent on loan from Nantes, this fearless, athletic defender is as comfortable marshaling the backline as he is sparking attacks from deep. Duverne has become a symbol of pride for Haitian fans, a guardian at the heart of their hopes and a story that’s still unfolding. Off the pitch, he’s quiet but intense, a steadfast presence whose story is still being written one fearless tackle at the time."} },
  { number: 24, name: 'Wilguens Paugain', position: 'DF', age: 24, club: 'Zulte Waregem', bio: {"es":"El currículum de Paugain parece un guión de película: nacido en la extrema pobreza en Thomazeau (Haití), fue adoptado a los cinco años por una familia de la Francia rural y fue descubierto por Nancy-Lorraine a los 12. Sin embargo, sufrió una grave lesión a los 18 que descarriló su carrera, lo obligó a abandonar el deporte durante ocho meses, le costó la oportunidad de un contrato profesional y lo empujó a trabajar durante un tiempo repartiendo pizzas. Pero se defendió y procedió a abrirse camino a través de vestuarios repartidos por Chipre, Letonia y Austria, añadiendo cada parada una nueva capa a su juego, antes de llegar a Bélgica. Paugain es el tipo de lateral que corre primero y piensa después, pero su instinto normalmente resulta acertado. Combina atletismo puro con una creciente ventaja técnica, avanzando como si la línea de banda fuera una pasarela. “Ésta es una oportunidad para que el mundo deje de descuidar a Haití”, afirma. \"Cuando la gente habla del país, habla de desastres naturales, inestabilidad política y pandillas, rara vez de algo positivo. Espero que la Copa del Mundo devuelva el respeto a nuestro equipo y a nuestro país\".","en":"Paugain’s CV reads like a movie script: born in extreme poverty in Thomazeau in Haiti he was adopted aged five by a family in rural France and was spotted by Nancy-Lorraine aged 12. However, he suffered a serious injury at 18 that derailed his career, forced him out of the game for eight months, cost him the chance of a professional contract and pushed him to work for a while delivering pizzas. But he fought back, and proceeded to play his way through dressing rooms scattered across Cyprus, Latvia and Austria, each stop adding a new layer to his game, before reaching Belgium. Paugain is the kind of full-back who sprints first and thinks later, but his instinct is normally proved right. He mixes raw athleticism with a growing technical edge, surging forward as if the touchline were a runway. “This is an opportunity for the world to stop neglecting Haiti,” he says. “When people talk about the country it is natural disasters, political instability and gangs, rarely about anything positive. I hope the World Cup will bring respect back to our team and our country.”"}, special: "Ex- pizza delivery guy" },
  // Volantes
  { number: 6, name: 'Carl Fred Sainté', position: 'MF', age: 23, club: 'El Paso Locomotive', bio: {"es":"En Grand-Goâve de Haití, mucho antes de acostumbrarse a las luces de los estadios y a los reflectores de la MLS, Sainté aprendió a jugar en canchas polvorientas donde la pelota rebotaba como una pregunta. Ahora responde a esas preguntas con autoridad. Alto, elegante y engañosamente rápido sobre el césped, Sainté es un mediocampista que cubre el terreno sin esfuerzo, gana cabezazos con sincronización y atraviesa el tráfico como si pudiera ver los movimientos antes de que sucedan. Ayudó a Violette a conseguir un título de liga haitiano, levantó la corona MLS NEXT Pro con North Texas y ascendió a la Major League Soccer con Dallas. Para Haití, juega con orgullo en cada entrada, tranquilo en medio del caos y valiente en el aire. Sus compañeros lo llaman el Metrónomo, porque cuando Sainté se mueve, todo el equipo encuentra su ritmo. “No sólo nos clasificamos, llevamos el latido del corazón de una nación al campo”, escribió después de que Haití sellara su lugar en la Copa Mundial. “Haití ha pasado por muchas cosas, pero seguimos mostrándole al mundo cómo es la resiliencia”.","en":"In Haiti’s Grand-Goâve, long before he became used to stadium floodlights and the MLS spotlight, Sainté learned to play on dusty pitches where the ball bounced like a question. He answers those questions now with authority. Tall, elegant and deceptively quick across the turf, Sainté is a midfielder who covers ground effortlessly, wins headers with timing, and threads passes through traffic as if he can see moves before they happen. He helped Violette to a Haitian league title, lifted the MLS NEXT Pro crown with North Texas, and climbed into Major League Soccer with Dallas. For Haiti, he plays with pride stitched into every tackle, calm amid chaos, brave in the air. Teammates call him the Metronome, because when Sainté moves, the whole team finds its rhythm. “We didn’t just qualify, we carried the heartbeat of a nation onto the pitch,” he wrote after Haiti sealed their World Cup spot. “Haiti has been through so much, but we keep showing the world what resilience looks like.”"} },
  { number: 10, name: 'Jean-Ricner Bellegarde', position: 'MF', age: 27, club: 'Wolves', bio: {"es":"Si el centro del campo fuera un tablero de ajedrez, Jean Ricner Bellegarde sería la reina: rápida, versátil e imposible de contener. Nacido en Colombes, Francia, perfeccionó su oficio en los sistemas juveniles locales. En Estrasburgo, se ganó la reputación de correr velozmente, tener una visión aguda y tacleadas intrépidas, rasgos que lo llevaron al Wolverhampton Wanderers en la Premier League. Apodado El Arquitecto, Bellegarde se nutre de dictar el ritmo, realizar pases que parecen imposibles y provocar contraataques de la nada. Al cambiar su lealtad a Haití después de representar a Francia a nivel juvenil, aportó estilo y compostura a la selección nacional, inspirando a jugadores jóvenes de todo el Caribe. “Tiene una habilidad natural para acelerar y herir al oponente”, dijo una vez su ex entrenador de Estrasburgo, Thierry Laurey, una frase que captura perfectamente el impulso, la inteligencia y la imprevisibilidad que definen el juego de Bellegarde.","en":"If midfield were a chessboard, Jean Ricner Bellegarde would be the queen: fast, versatile, and impossible to contain. Born in Colombes, France, he honed his craft in the local youth systems. At Strasbourg, he earned a reputation for darting runs, sharp vision, and fearless tackles, traits that carried him to Wolverhampton Wanderers in the Premier League. Nicknamed The Architect, Bellegarde thrives on dictating tempo, threading passes that seem impossible, and sparking counterattacks from nothing. Switching allegiance to Haiti after representing France at youth level, he brought flair and composure to the national side, inspiring young players across the Caribbean. “He has a natural ability to accelerate and hurt the opponent,” his former Strasbourg coach Thierry Laurey once said, a line that captures perfectly the burst, intelligence, and unpredictability that define Bellegarde’s game."}, special: "‘The Architect’" },
  { number: 14, name: 'Leverton Pierre', position: 'MF', age: 27, club: 'Vizela', bio: {"es":"Hay una historia que cuentan en Tabarre, Haití, de un niño flaco que perseguía pelotas sobre cemento agrietado y llevaba sueños mucho más grandes que sus botas. Ese niño se convirtió en Leverton Pierre, un centrocampista incansable. Su estilo es simple pero letal: rompe líneas con un pase preciso, retrocede con determinación tenaz y lee el juego como un veterano. En una fría noche de 2017, firmó su primer contrato profesional en Francia con el Bastia, y desde entonces ha sido el tipo de jugador que adoran los entrenadores. Puede que la carrera de Pierre no brille en los titulares, pero tiene un título de la Ligue2 y se ha convertido en un pilar de Haití, participando en tres Copas Oro de la Concacaf y en todos menos uno de sus clasificatorios para esta Copa del Mundo. Dato curioso: una vez persiguió a un perro que robó la pelota del partido por el vecindario y solo se detuvo cuando enterró la pelota en el jardín de alguien.","en":"There’s a story they tell in Tabarre, Haiti, of a skinny kid chasing balls over cracked concrete, carrying dreams much bigger than his boots. That boy became Leverton Pierre, a tireless midfielder. His style is simple but deadly: he breaks lines with a crisp pass, tracks back with dogged determination, and reads the game like a veteran. On a cool night in 2017 he signed his first pro contract in France with Bastia, and ever since he’s been the kind of player coaches love. Pierre’s career may not glitter with headlines, but he has a Ligue 2 title and has become a mainstay for Haiti, turning out in three Concacaf Gold Cups and in all but one of their qualifiers for this World Cup. Fun fact: He once chased a dog that stole the match ball across the neighbourhood, only stopping when it buried the ball in someone’s garden."} },
  { number: 17, name: 'Danley Jean Jacques', position: 'MF', age: 26, club: 'Philadelphia Union', bio: {"es":"En las bulliciosas canchas del Petit-Goâve de Haití, Danley Jean Jacques abordó como si la supervivencia estuviera en juego. Sus amigos juran que odiaba tanto la derrota que repetía los partidos en su cabeza antes de dormir. Ese fuego lo llevó desde el equipo campeón nacional de Don Bosco hasta la dura rutina de Metz y luego a Filadelfia en 2024. Rápido en el césped, poderoso en el aire y valiente en el duelo, juega como una tormenta en el corazón del mediocampo. En Francia, Jean Jacques arrasó en los partidos, ayudando a Metz a conseguir el ascenso a la Ligue 1. Para Haití ha marcado goles vitales, con los puños cerrados y los ojos cerrados en señal de gratitud, mientras los Granaderos perseguían la historia. Cinco años después de dejar Haití para ir a Francia, no ha perdido su amor por la cultura y la cocina haitianas: su favorito es el diri ak sos pwa, arroz con puré de frijoles negros. \"Eso es lo mejor\", dice. \"Especialmente cuando mi madre lo cocina\". Se sentirá especialmente como en casa cuando Haití juegue contra Brasil: el partido se jugará en el estadio de Filadelfia, su estadio.","en":"On the bustling pitches of Haiti’s Petit-Goâve, Danley Jean Jacques tackled as if survival was on the line. Friends swear he hated defeat so much he replayed matches in his head before sleep. That fire carried him from Don Bosco’s domestic title-winners to the hard grind of Metz, and on to Philadelphia in 2024. Quick across the grass, powerful in the air and fearless in the duel, he plays like a storm at the heart of midfield. In France Jean Jacques bulldozed through games, helping Metz secure promotion to Ligue 1. For Haiti he has scored vital goals, fists clenched, eyes closed in gratitude, as the Grenadiers chased history. Five years after leaving Haiti for France he has not lost his love of Haitian culture and cuisine - his favourite is diri ak sos pwa, rice with a black bean puree. “That’s the best,” he says. “Especially when my mother cooks it.” Will feel particularly at home when Haiti play Brazil – the game will be played at Philadelphia Stadium, his home ground."} },
  { number: 25, name: 'Dominique Simon', position: 'MF', age: 0, club: 'Tatran Presov', bio: {"es":"El viaje de Simon ha sido todo menos ordinario. Desde Francia hasta Estonia, Georgia, Chequia y ahora Eslovaquia, Simon ha construido su carrera de la manera más difícil, adquiriendo experiencia en toda Europa. Hay algo claramente parisino en su forma de jugar: tranquilo bajo presión, técnicamente pulido y siempre un paso por delante. Formado en la exigente academia del Paris St-Germain, aprendió temprano que la supervivencia en el fútbol de élite depende tanto de la inteligencia como del talento. Rápido en el campo, agudo en la entrada y sorprendentemente fuerte en el aire, mezcla acero con sutileza, capaz de interrumpir el juego en un momento y lanzar ataques con un solo pase preciso al siguiente. Simon encarna el talento de la diáspora de nueva generación de Haití: culto, resiliente y discretamente ambicioso. El tipo de mediocampista en el que confían los entrenadores, en el que se apoyan los compañeros y al que los oponentes rara vez disfrutan enfrentar.","en":"Simon’s journey has been anything but ordinary. From France to Estonia, Georgia, Czechia and now Slovakia, Simon has built his career the hard way, gaining experience across Europe. There is something distinctly Parisian about the way he plays: calm under pressure, technically polished and always a step ahead. Formed in the demanding academy of Paris St-Germain, he learned early that survival in elite football depends as much on intelligence as flair. Quick across the ground, sharp in the tackle and surprisingly strong in the air, he mixes steel with subtlety, capable of breaking up play one moment and launching attacks with a single crisp pass the next. Simon embodies Haiti’s new-generation diaspora talent: cultured, resilient and quietly ambitious. The kind of midfielder coaches trust, teammates lean on and opponents rarely enjoy facing."}, special: "Journeyman" },
  { number: 26, name: 'Woodensky Pierre', position: 'MF', age: 21, club: 'Violette AC', bio: {"es":"En el ruido de la Cité Soleil de Haití, donde el fútbol se juega por instinto y supervivencia, Pierre aprendió temprano que la vacilación sale cara. Los amigos recuerdan a un niño flaco que perseguía juegos desde el amanecer hasta la farola, sin miedo en el aire a pesar de su tamaño, y ya ladrando instrucciones como un veterano. Ahora en Real Hope FA, Pierre es un ancla en el mediocampo con ventaja y elegancia: rápido en distancias cortas y lo suficientemente hábil para escapar de espacios reducidos antes de realizar una entrada. Ascendió a través de Violette, recibió honores nacionales y obtuvo reconocimiento como uno de los jóvenes ejecutores más confiables de Haití.  “Trabaja duro y cree en ti mismo”, dice, una mentalidad moldeada por su educación. Con la vista puesta en el éxito en la Copa Mundial de 2026, Pierre juega como un hombre con una misión, llevando no sólo el balón, sino también las esperanzas de su lugar de origen.","en":"In the noise of Haiti’s Cité Soleil, where football is played on instinct and survival, Pierre learned early that hesitation is expensive. Friends recall a skinny kid chasing games from sunrise to streetlight, fearless in the air despite his size, already barking instructions like a veteran. Now at Real Hope FA, Pierre is a midfield anchor with edge and elegance: quick over short distances, and skilful enough to slip out of tight spaces before snapping into a tackle. He rose through Violette, collecting domestic honours and earning recognition as one of Haiti’s most reliable young enforcers.  “Work hard and believe in yourself,” he says, a mentality shaped by his upbringing. With his eyes on success at  the 2026 World Cup, Pierre plays like a man on a mission, carrying not just the ball, but the hopes of where he came from."} },
  // Delanteros
  { number: 7, name: 'Derrick Etienne Jr', position: 'FW', age: 29, club: 'Toronto FC', bio: {"es":"Hay algo eléctrico en Derrick Etienne Jr cuando enfrenta a un defensor: un movimiento, una explosión, y de repente corre por el flanco. Nacido en Virginia pero criado con una dieta de orgullo haitiano, siguió a su padre (también Derrick) al equipo nacional y, a su vez, fue seguido por su hermano, Danielle. Cuando se comprometió por primera vez con Haití, habló con el entusiasmo de un jugador que abraza algo más que el fútbol: \"Estoy emocionado de empezar... Creo que tendré la oportunidad de ser parte de algo especial\". Resultó ser más que palabras y se convirtió en una misión. Rápido, hábil y sorprendentemente fuerte en el aire, Etienne disfruta de los grandes momentos. Con el Columbus Crew levantó la Copa MLS en 2020, uno de varios honores en una trayectoria de la MLS que ha estado marcada por la resiliencia y la reinvención.","en":"There is something electric about Derrick Etienne Jr when he squares up a defender: a shimmy, a burst, and suddenly he’s streaking down the flank. Born in Virginia but raised on a diet of Haitian pride, he followed his father – also Derrick – into the national team and was in turn followed by his brother, Danielle. When he first committed to Haiti, he spoke with the eagerness of a player embracing more than just football: “I’m just excited to get started… I think I’ll have a chance to be part of something special.” It proved more than words, and became a mission. Fast, skilful and surprisingly strong in the air, Etienne thrives on big moments. With the Columbus Crew he lifted the MLS Cup in 2020, one of several honors in an MLS journey that has been shaped by resilience and reinvention."} },
  { number: 9, name: 'Duckens Nazon', position: 'FW', age: 31, club: 'Esteghlal', bio: {"es":"Conocido por su ritmo, su físico y su habilidad para encontrar la red en los escenarios más importantes, Nazon ciertamente no se pierde en los partidos, sino que choca contra ellos. Criado en los suburbios de París, aprendió desde temprano que el espacio hay que ganarlo, no regalarlo. Esa ventaja lo siguió desde la academia de Lorient a estadios de todos los continentes: sus empleadores actuales, el Esteghlal, con sede en Teherán, son el undécimo equipo de su carrera absoluta, que incluyó temporadas en Coventry, Oldham y St Mirren y períodos en Bulgaria e India. Se le conoce como La Bestia, y no en vano. Nazón tiene la costumbre de guardar lo mejor de sí para las noches más ruidosas: eliminatorias para la Copa del Mundo, batallas de la Concacaf, momentos en los que los nervios se tensan. Antes del decisivo partido de clasificación contra Nicaragua, Nazón pronunció un discurso en el vestuario: \"Aquí en Haití, algunas personas sólo tienen unos pocos dólares en el bolsillo. No tienen nada más. Sólo nos tienen a nosotros\", dijo. \"Si no ganamos, no les queda nada. Hoy tenemos la oportunidad de darles una sonrisa. Podemos hacerlos llorar de alegría. Cuentan con nuestros pies. Por favor, no los defraudemos\". Sus palabras surtieron efecto.","en":"Known for his pace, physicality, and knack for finding the net on the biggest stages, Nazon certainly doesn’t drift through matches, he crashes into them. Raised in the Paris suburbs, he learned early that space has to be earned, not given. That edge followed him from Lorient’s academy to stadiums across continents – his current employers, the Tehran-based Esteghlal, are the 11th team of his senior career, which has included stints at Coventry, Oldham and St Mirren and periods in Bulgaria and India. He is known as The Beast, and not for nothing. Nazon has a habit of saving his best for the loudest nights: World Cup qualifiers, Concacaf battles, moments when nerves tighten. Before the decisive qualifier against Nicaragua Nazon gave a speech in the dressing room: “Here in Haiti, some people only have a few dollars in their pockets. They have nothing else. They only have us,” he said. “If we don’t win, they have nothing left. Today, we have the chance to give them a smile. We can make them cry with joy. They are counting on our feet. Please, don’t let them down.” His words did the trick."} },
  { number: 11, name: 'Louicius Deedson', position: 'FW', age: 24, club: 'FC Dallas', bio: {"es":"Lo primero que llama la atención sobre Deedson es lo borroso: cuando los defensores reaccionan, ya se ha ido. Desde Haití hasta los Estados Unidos (donde se mudó originalmente cuando tenía 15 años) pasando por los terrenos azotados por el viento de Dinamarca, para Deedson, cada sprint se siente personal, cada gol, un mensaje a casa. Juega al borde del caos: hábil, siempre avanzando como si el campo se inclinara a su favor. Para Haití, se ha convertido en más que una amenaza: es una chispa. Marcó el primer gol del partido contra Nicaragua que selló el lugar de su nación al Mundial, un gol cargado de historia. Deedson aún no se define por los trofeos, sino por el sentimiento que deja atrás. \"Esta es la mejor sensación de mi carrera hasta ahora\", dijo sobre ese gol. \"Es mi sentimiento, y luego el sentimiento de los fanáticos, y luego el sentimiento de mi familia en casa\". Fuera de la cancha, está más tranquilo, cimentado en su trayectoria. Sus allegados hablan de un jugador profundamente apegado a Haití, que lleva con orgullo su bandera allá donde va, como si el fútbol no fuera sólo una carrera, sino una responsabilidad.","en":"The first thing you notice about Deedson  is the blur: by the time defenders react, he is already gone. From Haiti to the United States – where he originally moved aged 15 – via the windswept grounds of Denmark, for Deedson, every sprint feels personal, every goal a message home. He plays on the edge of chaos: skilful, always driving forward as if the pitch was tilting in his favour. For Haiti, he has become more than a threat: he’s a spark. He scored the opening goal in the game against Nicaragua that sealed his nation’s place at the World Cup, a strike loaded with history. Deedson isn’t defined by trophies, yet, but by the feeling he leaves behind. “This is the best feeling in my career so far,” he said of that goal. “It’s my feeling, and then the fans’ feeling, and then my family feeling back home.” Off the pitch, he is quieter, grounded by his journey. Those close to him speak of a player deeply attached to Haiti, carrying its flag with pride wherever he goes like football is not just a career, but a responsibility."} },
  { number: 15, name: 'Ruben Providence', position: 'FW', age: 24, club: 'Almere City FC', bio: {"es":"En las canchas de la academia del Paris St-Germain, Providence era el tipo de extremo que convertía el entrenamiento en un teatro: pasos elevados, ráfagas de ritmo y defensores persiguiendo sombras. Ese instinto se formó en sus primeros días en el club, pero cuando se mudó a la Roma en 2019, el estilo crudo había encontrado estructura, moldeado en uno de los entornos más exigentes de Europa, donde obtuvo honores juveniles y una ventaja táctica más aguda. Rápido y hábil, Providence juega con la libertad de un futbolista callejero y la disciplina de un graduado de dos gigantes europeos. Su paso por el TSV Hartberg añadió acero a su seda, aportando goles, asistencias y gusto por la lucha. Ahora, en el Almere City de la segunda división holandesa, juega con libertad y determinación. En 2025 eligió representar a Haití, una decisión basada más en el orgullo que en la conveniencia. Providence no se limita a seguir una carrera; está persiguiendo una historia que vale la pena contar.","en":"On the pitches of Paris St-Germain’s academy, Providence was the kind of winger who turned training into theatre: stepovers, bursts of pace, and defenders left chasing shadows. That instinct was shaped in his early days at the club but by the time he moved to Roma in 2019, the raw flair had found structure, shaped in one of Europe’s most demanding environments, where he picked up youth honours and a sharper tactical edge. Fast and skilful, Providence plays with the freedom of a street footballer and the discipline of a graduate from two European giants. His spell at TSV Hartberg added steel to his silk, bringing goals, assists and a taste for the fight. Now at Almere City in the Dutch second flight, he plays with freedom and intent. In 2025 he chose to represent Haiti, a decision rooted in pride more than convenience. Providence isn’t just chasing a career; he’s chasing a story worth telling."} },
  { number: 16, name: 'Lenny Joseph', position: 'FW', age: 25, club: 'Ferencvaros', bio: {"es":"Joseph siempre ha jugado como si tuviera que estar en algún lugar. Hay algo del futbolista callejero en él: agudo, intrépido y siempre jugando como si el siguiente toque pudiera cambiarlo todo. Criado en París y perfeccionado en la academia del Paris St-Germain, creció en un mundo donde el estilo era moneda de cambio y la supervivencia significaba destacar. Su ascenso en el fútbol francés finalmente lo llevó a Budapest y Ferencvaros, donde las noches europeas y el éxito nacional han agudizado su ventaja. Relámpago en las primeras cinco yardas, inteligente en el aire a pesar de su complexión delgada y lo suficientemente hábil para derribar a los defensores en espacios reducidos, tiene esa rara habilidad de hacer que el caos parezca coreografiado. Con sólo 25 años, juega con un hambre inquietante: el tipo de delantero que parece tratar cada carrera como una declaración. Para Haití, Joseph representa más que una promesa: parece el próximo titular a punto de suceder.","en":"Joseph has always played like he has somewhere to be. There is something of the street footballer about him: sharp, fearless and always playing as if the next touch might change everything. Raised in Paris and polished in the academy of Paris St-Germain, he grew up in a world where flair was currency and survival meant standing out. His rise through French football eventually led him to Budapest and Ferencvaros, where European nights and domestic success have sharpened his edge. Lightning over the first five yards, clever in the air despite his lean frame and skilful enough to unpick defenders in tight spaces, he carries that rare ability to make chaos look choreographed. Still only 25, he plays with a restless hunger: the kind of striker who seems to treat every run as a statement. For Haiti, Joseph represents more than promise: he looks like the next headline waiting to happen."}, special: "Surprise call-up" },
  { number: 18, name: 'Wilson Isidor', position: 'FW', age: 25, club: 'Sunderland', bio: {"es":"Isidor era el chico de Rennes que perseguía el fútbol como si le debiera algo, corriendo entre coches en campos improvisados ​​en callejones, celebrando goles imaginarios. Alto y rápido con instinto de depredador, es igualmente peligroso en el aire y en los giros, combinando fuerza con una gracia sorprendente. Su viaje lo llevó desde las categorías inferiores del Mónaco hasta los trofeos en Rusia con el Zenit de San Petersburgo, donde levantó títulos de liga y copa antes de lanzarse al ataque del Sunderland. Había representado a Francia en todas las categorías, pero en marzo, Haití finalmente consiguió a su hombre, Isidor confirmó su tan esperada decisión en las redes sociales: \"He visto todos tus mensajes... preguntaste por mí, me esperaste y aquí estoy\". Hizo su debut completo contra Islandia y marcó su primer gol en el mismo partido. Aporta un verdadero pedigrí a la delantera de Haití, la promesa no sólo de goles sino también del encendido del sueño mundialista de una nación.","en":"Isidor was the boy in Rennes who chased football like it owed him something, darting between cars on makeshift alleyway pitches, celebrating imaginary goals. Tall and quick with a predator’s instinct, he is equally dangerous in the air and on the turn, blending force with surprising grace. His journey took him from Monaco’s youth ranks to trophies in Russia with Zenit St Petersburg, where he lifted league and cup silverware before sprinting into Sunderland’s attack. He had represented France through the age levels but in March, Haiti finally got its man, Isidor confirming his long-awaited decision on social media: “I’ve seen all your messages … you asked for me, you waited for me, and here I am.” He made his full debut against Iceland, and scored his first goal in the same game. He brings real pedigree to Haiti’s forward line, the promise not just of goals but the ignition of a nation’s World Cup dream."}, special: "Main attacking threat" },
  { number: 19, name: 'Yassin Fortuné', position: 'FW', age: 27, club: 'Vizela', bio: {"es":"En el Arsenal se cuenta una historia sobre un Fortuné adolescente que dejaba a los defensores persiguiendo sombras, con un ritmo imposible de controlar. Pero fuera del terreno de juego, la historia se suaviza. Criada en los suburbios de París en una familia muy unida, Fortuné sigue estando profundamente arraigado y es más probable que pase tiempo con sus seres queridos que persiga los titulares. El Arsenal lo fichó procedente del Lens a los 16 años, pero nunca jugó para su primer equipo y se mudó al Sion en Suiza tres años después. El verano pasado fichó por el Vizela de la segunda división portuguesa y al cabo de un mes ya era internacional absoluto, habiendo representado a Francia en varias categorías inferiores. Fortuné es explosivo, hábil y sorprendentemente fuerte en el aire. Los compañeros de equipo suelen describir a un personaje tranquilo, concentrado, alguien que deja que su fútbol hable por sí solo. Sin embargo, también hay un lado lúdico, caracterizado por la música, las risas en el vestuario y ese inconfundible toque de fútbol callejero que nunca lo abandonó del todo.","en":"There’s a story told at Arsenal about a teenage Fortuné leaving defenders chasing shadows, his pace impossible to cage. But away from the pitch, the story softens. Raised in the Paris suburbs in a tight-knit family, Fortuné remains deeply grounded, more likely to spend time with loved ones than chase headlines. Arsenal signed him from Lens at 16 but he never played for their first team, moving to Sion in Switzerland three years later. Last summer he joined the Portuguese second-tier side Vizela and within a month was a full international, having represented France at various youth levels. Fortuné is explosive, skilful, and surprisingly strong in the air. Teammates often describe a quiet character, focused, someone who lets his football do the talking. Yet there’s a playful side too, characterised by music, dressing room laughter, and that unmistakable street-football edge that never quite left him."} },
  { number: 20, name: 'Frantzdy Pierrot', position: 'FW', age: 31, club: 'AEK Athens', bio: {"es":"Cuando Pierrot se lanza al aire, el tiempo parece detenerse. Entonces la red se ondula. Apodado “La Montaña”, el delantero haitiano hace que los cabezazos parezcan inevitables, dominando a los centrales en el aire y sorprendiéndolos en el césped con toques suaves y despidos inteligentes. Nacido en Cabo Haitiano pero criado en Massachusetts, su viaje a Europa no fue nada sencillo: pasó por el fútbol universitario estadounidense antes de aprender a prosperar bajo presión en escenarios más importantes de Bélgica, Francia, Israel y Grecia. En el AEK Atenas parecía destinado a convertirse en el punto de referencia en la delantera, el hombre que buscan sus compañeros cuando los partidos se aprietan y los centros empiezan a volar. Pero una lesión lo expulsó del equipo a finales del año pasado, y en febrero se mudó cedido al Caykur Rizespor de Turquía. Fuera del campo, Pierrot mantiene un perfil bajo. Un habitual de Haití, y con un impresionante promedio de 1,5 partidos por gol, lleva las expectativas de su país con silencioso orgullo, reflejando una personalidad que es más mesurada que llamativa: enfocada, sólida y construida alrededor del esfuerzo colectivo en lugar de la atención individual.","en":"When Pierrot launches himself into the air, time seems to pause. Then the net ripples. Nicknamed “The Mountain”, the Haitian striker makes headers feel inevitable, overpowering centre-backs in the air while surprising them on the turf with soft touches and clever layoffs. Born in Cap-Haïtien but brought up in Massachusetts, his journey to Europe was anything but straightforward, passing through American college soccer before he learned to thrive under pressure on bigger stages in Belgium, France, Israel and Greece. At AEK Athens he seemed set to become the reference point up front, the man teammates search for when matches tighten and crosses start flying. But injury pushed him out of the team towards the end of last year, and he moved on loan to Turkey’s Caykur Rizespor in February. Off the pitch Pierrot keeps a low profile. A regular for Haiti, and averaging an impressive 1.5 games per goal, he carries his country’s expectations with quiet pride, reflecting a personality that is more measured than flashy: focused, grounded, and built around collective effort rather than individual spotlight."} },
  { number: 21, name: 'Josué Casimir', position: 'FW', age: 24, club: 'Auxerre', bio: {"es":"En las soleadas canchas de Guadalupe, Josué Casimir aprendió fútbol de la manera más dura. Sin espacio, sin tiempo, sólo instinto. Creció en un hogar donde el juego era menos un pasatiempo que un idioma. Cuando llegó a la academia de Le Havre, ya jugaba desafiante. Los entrenadores aprendieron rápidamente a no enjaularlo. “Déjalo correr”, bromeó uno, y corre. Casimir es eléctrico: rápido en más de cinco yardas, valiente en el aire aunque no es particularmente alto y bendecido con la arrogancia de un extremo. No sólo vence a los defensores; él se burla de ellos. Juega con una sonrisa que casi se puede oír. Pero más allá del estilo hay algo más profundo. Jugó fútbol juvenil en Guadalupe, donde su hermano Stevenson juega en defensa, pero elegir Haití, la tierra natal de sus padres, le dio a su carrera un impulso diferente.","en":"On the sunlit pitches of Guadeloupe, Josué Casimir learned football the hard way. No space, no time, just instinct. He grew up in a household where the game was less a hobby than a language. By the time he reached Le Havre’s academy, he already played with defiance. Coaches quickly learned not to cage him. “Let him run,” one reportedly joked, and run he does. Casimir is electric: quick over five yards, fearless in the air though he is not particularly tall, and blessed with a winger’s swagger. He doesn’t just beat defenders; he teases them. He plays with a smile you can almost hear. But beyond the flair lies something deeper. He played youth football for Guadeloupe, for whom his brother Stevenson plays in defence, but choosing Haiti, his parents’ homeland, gave his career a different heartbeat."}, special: "Lightning quick" },
];

